class Solution {
  public int add(int a, int b) {
    while (b != 0) {
      int sum = a ^ b;
      int carry = (a & b) << 1;
      a = sum;
      b = carry;
    }
    return a;
  }
}

class Solution:
    def add(self, a: int, b: int) -> int:
        mask = 0xFFFFFFFF
        while b != 0:
            a, b = (a ^ b) & mask, ((a & b) << 1) & mask
        return a if a <= 0x7FFFFFFF else ~(a ^ mask)

impl Solution {
  pub fn add(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
      let sum = a ^ b;
      let carry = (a & b) << 1;
      a = sum;
      b = carry;
    }
    a
  }
}

const add = (a: number, b: number): number => {
  while (b !== 0) {
    const sum = a ^ b;
    const carry = (a & b) << 1;
    a = sum;
    b = carry;
  }
  return a;
};
